cssCode:
#container {
  width: 100%; height: 100%; background: #000; overflow: hidden;
  perspective: 1000px; /* ૩D ઊંડાણ માટે */
}
.grid-wrap {
  width: 200%; height: 200%; position: absolute; top: -50%; left: -50%;
  background-image: 
    linear-gradient(rgba(0, 255, 204, 0.3) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0, 255, 204, 0.3) 1px, transparent 1px);
  background-size: 50px 50px;
  /* ૩D માં નમાવવું */
  transform: rotateX(60deg) translateY(0px);
  animation: gridMove 2s linear infinite;
}
@keyframes gridMove {
  0% { transform: rotateX(60deg) translateY(0px); }
  100% { transform: rotateX(60deg) translateY(50px); } /* ગ્રીડને આગળ વધારવી */
}
.grid-overlay {
  position: absolute; inset: 0;
  background: radial-gradient(circle at center, transparent 30%, #000 70%);
  z-index: 2;
}

